{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title",
        "itinerary_image",
        "itinerary_heading_stack",
        "itinerary_description",
        "itinerary_table",
        "budget_heading_stack",
        "budget_table",
        "actions_section_title",
        "book_tea_button",
        "kenninji_info_button",
        "sources_section_title",
        "kyoto_tourism_button",
        "kenninji_official_button"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "Kyoto Zen & Matcha Tour",
        "variant": "h1"
      },
      "children": []
    },
    "itinerary_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/Kiyomizu-dera_Kyoto_Japan3121.jpg/1200px-Kiyomizu-dera_Kyoto_Japan3121.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "itinerary_heading_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "itinerary_section_title",
        "itinerary_icon"
      ]
    },
    "itinerary_section_title": {
      "type": "Text",
      "props": {
        "text": "November 15, 2024 Itinerary",
        "variant": "h2"
      },
      "children": []
    },
    "itinerary_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/map.svg"
      },
      "children": []
    },
    "itinerary_description": {
      "type": "Text",
      "props": {
        "text": "This 3.5 km route explores the Zen gardens and tea houses of Higashiyama, staying within a 6,000 JPY budget."
      },
      "children": []
    },
    "itinerary_table": {
      "type": "Table",
      "props": {
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "activity",
        "highlightColumns": [
          "time",
          "cost"
        ],
        "columns": [
          {
            "key": "time",
            "label": "Time"
          },
          {
            "key": "activity",
            "label": "Activity"
          },
          {
            "key": "description",
            "label": "Description"
          },
          {
            "key": "duration",
            "label": "Duration"
          },
          {
            "key": "cost",
            "label": "Cost"
          }
        ],
        "rows": [
          {
            "time": "09:00 AM",
            "activity": "Kyoto Station to Kennin-ji",
            "description": "Kyoto's oldest Zen temple.",
            "duration": "15m (Bus)",
            "cost": "0 JPY"
          },
          {
            "time": "09:30 AM",
            "activity": "Kennin-ji Temple",
            "description": "Famous for twin dragon ceiling.",
            "duration": "60 mins",
            "cost": "600 JPY"
          },
          {
            "time": "10:45 AM",
            "activity": "Walk to Kodai-ji",
            "description": "Zen rock garden.",
            "duration": "12 mins",
            "cost": "600 JPY"
          },
          {
            "time": "12:00 PM",
            "activity": "Lunch at Gion Tanto",
            "description": "Traditional okonomiyaki/bites.",
            "duration": "10 mins",
            "cost": "~1,800 JPY"
          },
          {
            "time": "01:15 PM",
            "activity": "Ich力 Tea House (Exterior)",
            "description": "Iconic Gion tea house.",
            "duration": "8 mins",
            "cost": "0 JPY"
          },
          {
            "time": "01:45 PM",
            "activity": "Tea Ceremony at Camellia",
            "description": "Authentic matcha experience.",
            "duration": "5 mins",
            "cost": "3,000 JPY"
          },
          {
            "time": "03:00 PM",
            "activity": "End of Tour",
            "description": "",
            "duration": "",
            "cost": "0 JPY"
          }
        ]
      },
      "children": []
    },
    "budget_heading_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "budget_section_title",
        "budget_icon"
      ]
    },
    "budget_section_title": {
      "type": "Text",
      "props": {
        "text": "Budget Summary",
        "variant": "h2"
      },
      "children": []
    },
    "budget_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/currency-yen.svg"
      },
      "children": []
    },
    "budget_table": {
      "type": "Table",
      "props": {
        "domain": "generic",
        "preferredPresentation": "cards",
        "primaryColumn": "item",
        "highlightColumns": [
          "amount"
        ],
        "columns": [
          {
            "key": "item",
            "label": "Item"
          },
          {
            "key": "amount",
            "label": "Amount"
          }
        ],
        "rows": [
          {
            "item": "Entrance Fees",
            "amount": "1,200 JPY"
          },
          {
            "item": "Lunch",
            "amount": "1,800 JPY"
          },
          {
            "item": "Tea Ceremony",
            "amount": "3,000 JPY"
          },
          {
            "item": "Total",
            "amount": "6,000 JPY (Perfectly on budget)"
          }
        ]
      },
      "children": []
    },
    "actions_section_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "book_tea_button": {
      "type": "Button",
      "props": {
        "label": "Book Tea Ceremony"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.camelliakyoto.com/book"
          }
        }
      }
    },
    "kenninji_info_button": {
      "type": "Button",
      "props": {
        "label": "More about Kennin-ji Temple"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.kenninji.jp/english/"
          }
        }
      }
    },
    "sources_section_title": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "kyoto_tourism_button": {
      "type": "Button",
      "props": {
        "label": "Kyoto Official Tourism Site",
        "variant": "borderless"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://kyoto.travel/en/"
          }
        }
      }
    },
    "kenninji_official_button": {
      "type": "Button",
      "props": {
        "label": "Kennin-ji Official Site",
        "variant": "borderless"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.kenninji.jp/english/"
          }
        }
      }
    }
  }
}
